// docker run -d -p 127.0.0.1:6379:6379 redis:7.4-alpine --maxmemory-policy noeviction
// npm install bullmq ioredis
import { Queue } from 'bullmq';
import { Redis } from 'ioredis';

// No BullMQ 6 o ioredis é opcional: em ESM, passe a instância pronta
const connection = new Redis({
  host: '127.0.0.1',
  port: 6379,
  maxRetriesPerRequest: null, // obrigatório para workers
});

const queue = new Queue('notificacoes', {
  connection,
  defaultJobOptions: {
    attempts: 3,
    backoff: { type: 'exponential', delay: 500 }, // 500ms, 1s, 2s...
    removeOnComplete: { count: 100 }, // sem limpeza, o Redis guarda tudo para sempre
    removeOnFail: { count: 500 },
  },
});

await queue.add('enviar-email', { to: 'ana@ex.com', subject: 'Oi', body: 'Olá!' });

// Quem cria a conexão fecha a conexão
await queue.close();
await connection.quit();

// jobs.ts: o contrato entre produtor e worker
export interface JobDataMap {
  'enviar-email': { to: string; subject: string; body: string };
  'gerar-relatorio': { userId: string; mes: string };
}
export interface JobResultMap {
  'enviar-email': { messageId: string };
  'gerar-relatorio': { url: string; linhas: number };
}
export type JobName = keyof JobDataMap; // 'enviar-email' | 'gerar-relatorio'

export type NotificacoesQueue = Queue<JobDataMap[JobName], JobResultMap[JobName], JobName>;

// O nome escolhido (K) define o formato obrigatório de `data`
export function enqueue<K extends JobName>(
  queue: NotificacoesQueue,
  name: K,
  data: JobDataMap[K],
  opts?: JobsOptions,
) {
  return queue.add(name, data, opts);
}

enqueue(queue, 'gerar-relatorio', { userId: 'u1', mes: '2026-10' }); // ✅

// @ts-expect-error: 'enviar-email' exige { to, subject, body }
enqueue(queue, 'enviar-email', { userId: 'u1', mes: '2026-10' });

// @ts-expect-error: job que não existe no contrato
enqueue(queue, 'apagar-tudo', {});

import { UnrecoverableError, Worker, type Job } from 'bullmq';

// Para cada nome K: recebe o job de K e devolve o resultado de K
type Handlers = {
  [K in JobName]: (job: Job<JobDataMap[K], JobResultMap[K], K>) => Promise<JobResultMap[K]>;
};

const handlers: Handlers = {
  'enviar-email': async (job) => {
    const { to } = job.data; // TS sabe que é { to, subject, body }
    if (!to.includes('@')) throw new UnrecoverableError(`endereço inválido: ${to}`);
    return { messageId: `msg-${job.id}` };
  },
  'gerar-relatorio': async (job) => {
    await job.updateProgress(50); // vira evento "progress"
    return { url: `/relatorios/${job.data.userId}/${job.data.mes}.pdf`, linhas: 42 };
  },
};

// Genérica em K: o handler escolhido e o job dependem do mesmo nome
function dispatch<K extends JobName>(job: Job<JobDataMap[K], JobResultMap[K], K>) {
  const handler = handlers[job.name];
  return handler(job);
}

const worker = new Worker<JobDataMap[JobName], JobResultMap[JobName], JobName>(
  'notificacoes',
  (job) => dispatch(job),
  { connection, concurrency: 3 }, // até 3 jobs ao mesmo tempo neste processo
);

// attemptsMade = tentativas que JÁ falharam (0 na primeira execução)
if (to.startsWith('instavel') && job.attemptsMade < 2) {
  throw new Error('timeout no SMTP'); // falha na 1ª e na 2ª, passa na 3ª
}

// Erro permanente: falha na hora, sem gastar as tentativas restantes
throw new UnrecoverableError('endereço inválido');

// Job atrasado: só fica disponível para o worker depois de 3s
await enqueue(queue, 'enviar-email', lembrete, { delay: 3_000 });

// Idempotência: mesmo jobId = mesmo job (enquanto ele existir no Redis)
await enqueue(queue, 'gerar-relatorio', dados, { jobId: 'relatorio-u2-2026-10' });
await enqueue(queue, 'gerar-relatorio', dados, { jobId: 'relatorio-u2-2026-10' });
// → 7 chamadas de add no exemplo, 6 jobs distintos

// Saída real do worker:
// ▶ enviar-email#3 (tentativa 1)
// ✖ enviar-email#3 falhou de vez após 1 tentativa(s): endereço inválido: sem-arroba
// ↻ enviar-email#2 falhou (timeout no SMTP); tentativa 1/3, vai tentar de novo
// ↻ enviar-email#2 falhou (timeout no SMTP); tentativa 2/3, vai tentar de novo
// ✔ enviar-email#2 → {"messageId":"msg-2"}

// Eventos deste processo
worker.on('completed', (job, result) => console.log(`✔ ${job.name}#${job.id}`, result));
worker.on('failed', (job, err) => {
  if (!job) return; // pode vir undefined
  const max = job.opts.attempts ?? 1;
  const definitivo = err instanceof UnrecoverableError || job.attemptsMade >= max;
  console.log(definitivo ? 'falhou de vez' : 'vai tentar de novo', err.message);
});
// Sem este listener, uma queda do Redis derruba o processo
worker.on('error', (err) => console.error('erro no worker:', err.message));

// Eventos da fila inteira, vindos de qualquer processo (conexão própria)
const events = new QueueEvents('notificacoes', {
  connection: new Redis({ maxRetriesPerRequest: null }),
});
events.on('retries-exhausted', ({ jobId, attemptsMade }) =>
  console.log(`#${jobId} esgotou as tentativas (${attemptsMade})`),
);

// Graceful shutdown: no deploy o processo recebe SIGTERM
process.once('SIGTERM', async () => {
  await worker.close(); // para de pegar jobs e espera os que estão rodando
  await connection.quit();
  process.exit(0);
});
